-- D&D 3.5 SRD/OGL catalog foundation; imported source text remains attributed and unverified until mechanics audit.
-- OGL source identifier: dnd35-srd-ogl. This migration does not mark rules as audited or implemented.
BEGIN;

INSERT INTO public.srd_spells
(id,nome,nivel,circulo,escola,alcance,alvo,area,duracao,componentes,classes,descricao,dados_tecnicos,srd_source_url,source_notes,source_id,source_status)
SELECT x.id,x.nome,x.nivel,x.circulo,x.escola,x.alcance,x.alvo,x.area,x.duracao,x.componentes,x.classes,x.descricao,x.dados_tecnicos,x.srd_source_url,x.source_notes,x.source_id,x.source_status
FROM jsonb_to_recordset($spells$[{"id":"srd35_spell_chaos_hammer","nome":"Martelo Caótico","nivel":null,"circulo":4,"escola":"Evocação","alcance":"Médio (30 m + 3 m/nível)","alvo":null,"area":"Explosão com raio de 6 m","duracao":"Instantânea; lentidão por 1d6 rodadas","componentes":"V, S","classes":[],"descricao":"Energia caótica causa dano a criaturas leais e pode deixá-las lentas. Criaturas neutras sofrem dano reduzido; um teste de Vontade reduz o dano e pode anular a lentidão.","dados_tecnicos":{"class_levels":{},"domain_levels":{"chaos":4},"source_name":"Chaos Hammer","source_field_values":{"Level":"Chaos 4","School":"Evocation [Chaotic]","Components":"V, S","Casting Time":"1 standard action","Range":"Medium (100 ft. + 10 ft./level)","Area":"20-ft.-radius burst","Duration":"Instantaneous (1d6 rounds); see text","Saving Throw":"Will partial; see text","Spell Resistance":"Yes"},"engine_status":"manual_only"},"srd_source_url":"https://www.d20srd.org/srd/spells/chaosHammer.htm","source_notes":"Magia do domínio Caos; efeito não automatizado.","source_id":"dnd35-srd-ogl","source_status":"unreviewed"},{"id":"srd35_spell_unholy_blight","nome":"Praga Profana","nivel":null,"circulo":4,"escola":"Evocação","alcance":"Médio (30 m + 3 m/nível)","alvo":null,"area":"Expansão com raio de 6 m","duracao":"Instantânea; condição por 1d4 rodadas","componentes":"V, S","classes":[],"descricao":"Poder profano causa dano a criaturas bondosas e pode deixá-las enjoadas; criaturas neutras sofrem dano reduzido.","dados_tecnicos":{"class_levels":{},"domain_levels":{"evil":4},"source_name":"Unholy Blight","source_field_values":{"Level":"Evil 4","School":"Evocation [Evil]","Components":"V, S","Casting Time":"1 standard action","Range":"Medium (100 ft. + 10 ft./level)","Area":"20-ft.-radius spread","Duration":"Instantaneous (1d4 rounds); see text","Saving Throw":"Will partial","Spell Resistance":"Yes"},"engine_status":"manual_only"},"srd_source_url":"https://www.d20srd.org/srd/spells/unholyBlight.htm","source_notes":"Magia do domínio Mal; efeito não automatizado.","source_id":"dnd35-srd-ogl","source_status":"unreviewed"},{"id":"srd35_spell_burning_hands","nome":"Mãos Flamejantes","nivel":null,"circulo":1,"escola":"Evocação","alcance":"15 pés","alvo":null,"area":"Cone de chamas","duracao":"Instantânea","componentes":"V, S","classes":["sorcerer","wizard"],"descricao":"Um cone de fogo causa 1d4 de dano por nível de conjurador, até 5d4; o teste de Reflexos reduz o dano à metade.","dados_tecnicos":{"class_levels":{"sorcerer":1,"wizard":1},"domain_levels":{"fire":1},"source_name":"Burning Hands","source_field_values":{"Level":"Fire 1, Sor/Wiz 1","School":"Evocation [Fire]","Components":"V, S","Casting Time":"1 standard action","Range":"15 ft.","Area":"Cone-shaped burst","Duration":"Instantaneous","Saving Throw":"Reflex half","Spell Resistance":"Yes"},"engine_status":"manual_only"},"srd_source_url":"https://www.d20srd.org/srd/spells/burningHands.htm","source_notes":"Magia de feiticeiro/mago e do domínio Fogo; efeito não automatizado.","source_id":"dnd35-srd-ogl","source_status":"unreviewed"},{"id":"srd35_spell_holy_smite","nome":"Golpe Sagrado","nivel":null,"circulo":4,"escola":"Evocação","alcance":"Médio (30 m + 3 m/nível)","alvo":null,"area":"Explosão com raio de 6 m","duracao":"Instantânea; cegueira por 1 rodada","componentes":"V, S","classes":[],"descricao":"Poder sagrado causa dano a criaturas malignas e pode cegá-las; criaturas neutras sofrem dano reduzido.","dados_tecnicos":{"class_levels":{},"domain_levels":{"good":4},"source_name":"Holy Smite","source_field_values":{"Level":"Good 4","School":"Evocation [Good]","Components":"V, S","Casting Time":"1 standard action","Range":"Medium (100 ft. + 10 ft./level)","Area":"20-ft.-radius burst","Duration":"Instantaneous (1 round); see text","Saving Throw":"Will partial; see text","Spell Resistance":"Yes"},"engine_status":"manual_only"},"srd_source_url":"https://www.d20srd.org/srd/spells/holySmite.htm","source_notes":"Magia do domínio Bem; efeito não automatizado.","source_id":"dnd35-srd-ogl","source_status":"unreviewed"},{"id":"srd35_spell_orders_wrath","nome":"Cólera da Ordem","nivel":null,"circulo":4,"escola":"Evocação","alcance":"Médio (30 m + 3 m/nível)","alvo":null,"area":"Criaturas não leais em um cubo de 9 m","duracao":"Instantânea; atordoamento por 1 rodada","componentes":"V, S","classes":[],"descricao":"Energia da ordem causa dano a criaturas caóticas e pode deixá-las atordoadas; criaturas neutras sofrem dano reduzido.","dados_tecnicos":{"class_levels":{},"domain_levels":{"law":4},"source_name":"Order’s Wrath","source_field_values":{"Level":"Law 4","School":"Evocation [Lawful]","Components":"V, S","Casting Time":"1 standard action","Range":"Medium (100 ft. + 10 ft./level)","Area":"Nonlawful creatures within a burst that fills a 30-ft. cube","Duration":"Instantaneous (1 round); see text","Saving Throw":"Will partial; see text","Spell Resistance":"Yes"},"engine_status":"manual_only"},"srd_source_url":"https://www.d20srd.org/srd/spells/ordersWrath.htm","source_notes":"Magia do domínio Ordem; efeito não automatizado.","source_id":"dnd35-srd-ogl","source_status":"unreviewed"},{"id":"srd35_spell_entangle","nome":"Emaranhar","nivel":null,"circulo":1,"escola":"Transmutação","alcance":"Longo (120 m + 12 m/nível)","alvo":null,"area":"Plantas em expansão com raio de 12 m","duracao":"1 minuto/nível (D)","componentes":"V, S, DF","classes":["druid","ranger"],"descricao":"A vegetação prende criaturas na área e pode deixá-las enredadas. Um teste de Reflexos bem-sucedido evita a condição, mas o deslocamento na área continua reduzido.","dados_tecnicos":{"class_levels":{"druid":1,"ranger":1},"domain_levels":{"plant":1},"source_name":"Entangle","source_field_values":{"Level":"Drd 1, Plant 1, Rgr 1","School":"Transmutation","Components":"V, S, DF","Casting Time":"1 standard action","Range":"Long (400 ft. + 40 ft./level)","Area":"Plants in a 40-ft.-radius spread","Duration":"1 min./level (D)","Saving Throw":"Reflex partial; see text","Spell Resistance":"No"},"engine_status":"manual_only"},"srd_source_url":"https://www.d20srd.org/srd/spells/entangle.htm","source_notes":"Magia de druida/ranger e do domínio Plantas; efeito não automatizado.","source_id":"dnd35-srd-ogl","source_status":"unreviewed"}]$spells$::jsonb) AS x(
 id text,nome text,nivel text,circulo smallint,escola text,alcance text,alvo text,area text,duracao text,componentes text,classes text[],descricao text,dados_tecnicos jsonb,srd_source_url text,source_notes text,source_id text,source_status text
)
ON CONFLICT(id) DO NOTHING;

INSERT INTO public.srd_conditions
(condition_id,name,summary,mechanical_effects,source_id,source_url,verification_status)
SELECT x.condition_id,x.name,x.summary,x.mechanical_effects,x.source_id,x.source_url,x.verification_status
FROM jsonb_to_recordset($conditions$[{"condition_id":"abilitydamaged","name":"Atributo danificado","summary":"Perdeu temporariamente pontos de um atributo; eles se recuperam à razão de 1 ponto por dia, salvo indicação diferente. Chegar a 0 pode incapacitar a criatura.","mechanical_effects":{"source_name":"Ability Damaged","source_text":"The character has temporarily lost 1 or more ability score points. Lost points return at a rate of 1 per day unless noted otherwise by the condition dealing the damage. A character with Strength 0 falls to the ground and is helpless. A character with Dexterity 0 is paralyzed. A character with Constitution 0 is dead. A character with Intelligence, Wisdom, or Charisma 0 is unconscious. Ability damage is different from penalties to ability scores, which go away when the conditions causing them go away.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"abilitydrained","name":"Atributo drenado","summary":"Perdeu permanentemente pontos de um atributo; a recuperação exige magia. Chegar a 0 pode incapacitar ou matar, conforme o atributo.","mechanical_effects":{"source_name":"Ability Drained","source_text":"The character has permanently lost 1 or more ability score points. The character can regain these points only through magical means. A character with Strength 0 falls to the ground and is helpless. A character with Dexterity 0 is paralyzed. A character with Constitution 0 is dead. A character with Intelligence, Wisdom, or Charisma 0 is unconscious.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"blinded","name":"Cego","summary":"Não enxerga: sofre –2 na CA, perde o bônus de Destreza na CA, desloca-se à metade e falha em testes que dependem da visão.","mechanical_effects":{"source_name":"Blinded","source_text":"The character cannot see. He takes a –2 penalty to Armor Class, loses his Dexterity bonus to AC (if any), moves at half speed, and takes a –4 penalty on Search checks and on most Strength- and Dexterity-based skill checks. All checks and activities that rely on vision (such as reading and Spot checks) automatically fail. All opponents are considered to have total concealment (50% miss chance) to the blinded character. Characters who remain blinded for a long time grow accustomed to these drawbacks and can overcome some of them.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"blownaway","name":"Arremessado pelo vento","summary":"Ventos muito fortes derrubam e arremessam a criatura, causando dano não letal conforme a distância.","mechanical_effects":{"source_name":"Blown Away","source_text":"Depending on its size, a creature can be blown away by winds of high velocity. A creature on the ground that is blown away is knocked down and rolls 1d4 x 10 feet, taking 1d4 points of nonlethal damage per 10 feet. A flying creature that is blown away is blown back 2d6 x 10 feet and takes 2d6 points of nonlethal damage due to battering and buffering.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"checked","name":"Contido","summary":"Uma força impede o avanço; a criatura para ou é empurrada para trás conforme seu modo de deslocamento.","mechanical_effects":{"source_name":"Checked","source_text":"Prevented from achieving forward motion by an applied force, such as wind. Checked creatures on the ground merely stop. Checked flying creatures move back a distance specified in the description of the effect.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"confused","name":"Confuso","summary":"No início de cada turno, role d% para determinar a ação: atacar, agir normalmente, ficar sem agir, fugir ou atacar a criatura mais próxima.","mechanical_effects":{"source_name":"Confused","source_text":"A _confused_ character’s actions are determined by rolling d% at the beginning of his turn: 01–10, attack caster with melee or ranged weapons (or close with caster if attacking is not possible); 11–20, act normally; 21–50, do nothing but babble incoherently; 51–70, flee away from caster at top possible speed; 71–100, attack nearest creature (for this purpose, a familiar counts as part of the subject’s self ). A _confused_ character who can’t carry out the indicated action does nothing but babble incoherently. Attackers are not at any special advantage when attacking a _confused_ character. Any _confused_ character who is attacked automatically attacks its attackers on its next turn, as long as it is still _confused_ when its turn comes. A _confused_ character does not make attacks of opportunity against any creature that it is not already devoted to attacking (either because of its most recent action or because it has just been attacked).","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"cowering","name":"Encolhido de medo","summary":"Fica paralisado de medo, sem agir; sofre –2 na CA e perde o bônus de Destreza.","mechanical_effects":{"source_name":"Cowering","source_text":"The character is frozen in fear and can take no actions. A cowering character takes a –2 penalty to Armor Class and loses her Dexterity bonus (if any).","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"dazed","name":"Pasmo","summary":"Não pode agir, mas não sofre penalidade na CA.","mechanical_effects":{"source_name":"Dazed","source_text":"The creature is unable to act normally. A dazed creature can take no actions, but has no penalty to AC.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"dazzled","name":"Ofuscado","summary":"Sofre –1 nas jogadas de ataque e em testes de Procurar e Observar sob luz intensa.","mechanical_effects":{"source_name":"Dazzled","source_text":"The creature is unable to see well because of overstimulation of the eyes. A dazzled creature takes a –1 penalty on attack rolls, Search checks, and Spot checks.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"dead","name":"Morto","summary":"Morreu; não pode agir nem ser curado por meios comuns.","mechanical_effects":{"source_name":"Dead","source_text":"The character’s hit points are reduced to –10, his Constitution drops to 0, or he is killed outright by a spell or effect. The character’s soul leaves his body. Dead characters cannot benefit from normal or magical healing, but they can be restored to life via magic. A dead body decays normally unless magically preserved, but magic that restores a dead character to life also restores the body either to full health or to its condition at the time of death (depending on the spell or device). Either way, resurrected characters need not worry about rigor mortis, decomposition, and other conditions that affect dead bodies.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"deafened","name":"Surdo","summary":"Não ouve; falha automaticamente em testes de Ouvir, sofre –4 na iniciativa e há 20% de chance de falha em magias com componente verbal.","mechanical_effects":{"source_name":"Deafened","source_text":"A deafened character cannot hear. She takes a –4 penalty on initiative checks, automatically fails Listen checks, and has a 20% chance of spell failure when casting spells with verbal components. Characters who remain deafened for a long time grow accustomed to these drawbacks and can overcome some of them.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"disabled","name":"Incapacitado","summary":"Com 0 PV, permanece consciente, mas só pode realizar uma ação padrão ou de movimento; esforço intenso causa 1 ponto de dano.","mechanical_effects":{"source_name":"Disabled","source_text":"A character with 0 hit points, or one who has negative hit points but has become stable and conscious, is disabled. A disabled character may take a single move action or standard action each round (but not both, nor can she take full-round actions). She moves at half speed. Taking move actions doesn’t risk further injury, but performing any standard action (or any other action the DM deems strenuous, including some free actions such as casting a quickened spell) deals 1 point of damage after the completion of the act. Unless the action increased the disabled character’s hit points, she is now in negative hit points and dying.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"dying","name":"Morrendo","summary":"Está inconsciente entre –1 e –9 PV e perde 1 PV por rodada até estabilizar ou morrer.","mechanical_effects":{"source_name":"Dying","source_text":"A dying character is unconscious and near death. She has –1 to –9 current hit points. A dying character can take no actions and is unconscious. At the end of each round (starting with the round in which the character dropped below 0 hit points), the character rolls d% to see whether she becomes stable. She has a 10% chance to become stable. If she does not, she loses 1 hit point. If a dying character reaches –10 hit points, she is dead.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"energydrained","name":"Drenado de energia","summary":"Recebeu níveis negativos que penalizam testes e podem reduzir PV, nível efetivo e capacidades.","mechanical_effects":{"source_name":"Energy Drained","source_text":"The character gains one or more negative levels, which might permanently drain the character’s levels. If the subject has at least as many negative levels as Hit Dice, he dies. Each negative level gives a creature the following penalties: –1 penalty on attack rolls, saving throws, skill checks, ability checks; loss of 5 hit points; and –1 to effective level (for determining the power, duration, DC, and other details of spells or special abilities). In addition, a spellcaster loses one spell or spell slot from the highest spell level castable.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"entangled","name":"Enredado","summary":"Sofre –2 nos ataques e –4 na Destreza, desloca-se à metade e não pode correr nem investir.","mechanical_effects":{"source_name":"Entangled","source_text":"The character is ensnared. Being entangled impedes movement, but does not entirely prevent it unless the bonds are anchored to an immobile object or tethered by an opposing force. An entangled creature moves at half speed, cannot run or charge, and takes a –2 penalty on all attack rolls and a –4 penalty to Dexterity. An entangled character who attempts to cast a spell must make a Concentration check (DC 15 + the spell’s level) or lose the spell.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"exhausted","name":"Exausto","summary":"Sofre –6 na Força e Destreza e desloca-se à metade; uma hora de descanso reduz a condição a fatigado.","mechanical_effects":{"source_name":"Exhausted","source_text":"An exhausted character moves at half speed and takes a –6 penalty to Strength and Dexterity. After 1 hour of complete rest, an exhausted character becomes fatigued. A fatigued character becomes exhausted by doing something else that would normally cause fatigue.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"fascinated","name":"Fascinado","summary":"Fixa a atenção em um estímulo e não age; ameaças ou distrações podem encerrar o efeito.","mechanical_effects":{"source_name":"Fascinated","source_text":"A fascinated creature is entranced by a supernatural or spell effect. The creature stands or sits quietly, taking no actions other than to pay attention to the fascinating effect, for as long as the effect lasts. It takes a –4 penalty on skill checks made as reactions, such as Listen and Spot checks. Any potential threat, such as a hostile creature approaching, allows the fascinated creature a new saving throw against the fascinating effect. Any obvious threat, such as someone drawing a weapon, casting a spell, or aiming a ranged weapon at the fascinated creature, automatically breaks the effect. A fascinated creature’s ally may shake it free of the spell as a standard action.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"fatigued","name":"Fatigado","summary":"Sofre –2 na Força e Destreza e não pode correr nem investir; descanso remove a condição.","mechanical_effects":{"source_name":"Fatigued","source_text":"A fatigued character can neither run nor charge and takes a –2 penalty to Strength and Dexterity. Doing anything that would normally cause fatigue causes the fatigued character to become exhausted. After 8 hours of complete rest, fatigued characters are no longer fatigued.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"flatfooted","name":"Desprevenido","summary":"Ainda não reagiu ao combate: perde o bônus de Destreza na CA e não pode realizar ataques de oportunidade.","mechanical_effects":{"source_name":"Flat-Footed","source_text":"A character who has not yet acted during a combat is flat-footed, not yet reacting normally to the situation. A flat-footed character loses his Dexterity bonus to AC (if any) and cannot make attacks of opportunity.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"frightened","name":"Amedrontado","summary":"Foge da fonte do medo; sofre –2 em ataques, testes de resistência e perícias enquanto puder escapar.","mechanical_effects":{"source_name":"Frightened","source_text":"A frightened creature flees from the source of its fear as best it can. If unable to flee, it may fight. A frightened creature takes a –2 penalty on all attack rolls, saving throws, skill checks, and ability checks. A frightened creature can use special abilities, including spells, to flee; indeed, the creature must use such means if they are the only way to escape.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"grappling","name":"Agarrado","summary":"Está agarrado; movimento e ataques ficam limitados, e a criatura precisa vencer testes opostos para agir ou escapar.","mechanical_effects":{"source_name":"Grappling","source_text":"Engaged in wrestling or some other form of hand-to-hand struggle with one or more attackers. A grappling character can undertake only a limited number of actions. He does not threaten any squares, and loses his Dexterity bonus to AC (if any) against opponents he isn’t grappling.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"helpless","name":"Indefeso","summary":"Não pode se defender; é tratado como Destreza 0 e ataques corpo a corpo recebem +4. Pode sofrer golpe de misericórdia.","mechanical_effects":{"source_name":"Helpless","source_text":"A helpless character is paralyzed, _held_, bound, sleeping, unconscious, or otherwise completely at an opponent’s mercy. A helpless target is treated as having a Dexterity of 0 (–5 modifier). Melee attacks against a helpless target get a +4 bonus (equivalent to attacking a prone target). Ranged attacks gets no special bonus against helpless targets. Rogues can sneak attack helpless targets.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"incorporeal","name":"Incorpóreo","summary":"Não possui corpo físico; ataques não mágicos geralmente têm 50% de chance de falha e efeitos de força funcionam normalmente.","mechanical_effects":{"source_name":"Incorporeal","source_text":"Having no physical body. Incorporeal creatures are immune to all nonmagical attack forms. They can be harmed only by other incorporeal creatures, +1 or better magic weapons, spells, spell-like effects, or supernatural effects.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"invisible","name":"Invisível","summary":"Não pode ser visto sem sentidos ou efeitos especiais; recebe vantagens contra criaturas que não localizam sua posição.","mechanical_effects":{"source_name":"Invisible","source_text":"Visually undetectable. An invisible creature gains a +2 bonus on attack rolls against sighted opponents, and ignores its opponents’ Dexterity bonuses to AC (if any). (See Invisibility, under Special Abilities.)","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"knockeddown","name":"Derrubado","summary":"Foi derrubado e fica caído; precisa gastar uma ação de movimento para se levantar.","mechanical_effects":{"source_name":"Knocked Down","source_text":"Depending on their size, creatures can be knocked down by winds of high velocity. Creatures on the ground are knocked prone by the force of the wind. Flying creatures are instead blown back 1d6 x 10 feet.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"nauseated","name":"Nauseado","summary":"Só pode realizar uma ação de movimento por rodada.","mechanical_effects":{"source_name":"Nauseated","source_text":"Experiencing stomach distress. Nauseated creatures are unable to attack, cast spells, concentrate on spells, or do anything else requiring attention. The only action such a character can take is a single move action per turn.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"panicked","name":"Em pânico","summary":"Foge da fonte do medo, larga o que segura e sofre –2 em ataques, testes de resistência e perícias.","mechanical_effects":{"source_name":"Panicked","source_text":"A panicked creature must drop anything it holds and flee at top speed from the source of its fear, as well as any other dangers it encounters, along a random path. It can’t take any other actions. In addition, the creature takes a –2 penalty on all saving throws, skill checks, and ability checks. If cornered, a panicked creature cowers and does not attack, typically using the total defense action in combat. A panicked creature can use special abilities, including spells, to flee; indeed, the creature must use such means if they are the only way to escape.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"paralyzed","name":"Paralisado","summary":"Não pode se mover nem agir; fica indefeso. Criaturas voadoras sem sustentação caem.","mechanical_effects":{"source_name":"Paralyzed","source_text":"A paralyzed character is frozen in place and unable to move or act. A paralyzed character has effective Dexterity and Strength scores of 0 and is helpless, but can take purely mental actions. A winged creature flying in the air at the time that it becomes paralyzed cannot flap its wings and falls. A paralyzed swimmer can’t swim and may drown. A creature can move through a space occupied by a paralyzed creature—ally or not. Each square occupied by a paralyzed creature, however, counts as 2 squares.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"petrified","name":"Petrificado","summary":"Transformou-se em pedra; não pode agir nem perceber o ambiente.","mechanical_effects":{"source_name":"Petrified","source_text":"A petrified character has been turned to stone and is considered unconscious. If a petrified character cracks or breaks, but the broken pieces are joined with the body as he returns to flesh, he is unharmed. If the character’s petrified body is incomplete when it returns to flesh, the body is likewise incomplete and there is some amount of permanent hit point loss and/or debilitation.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"pinned","name":"Imobilizado","summary":"Está imobilizado por um agarrão; sofre –4 na CA contra adversários que não o imobilizam.","mechanical_effects":{"source_name":"Pinned","source_text":"Held immobile (but not helpless) in a grapple.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"prone","name":"Caído","summary":"Está no chão; ataques corpo a corpo sofrem –4, ataques à distância contra si sofrem –4, e levantar-se exige movimento.","mechanical_effects":{"source_name":"Prone","source_text":"The character is on the ground. An attacker who is prone has a –4 penalty on melee attack rolls and cannot use a ranged weapon (except for a crossbow). A defender who is prone gains a +4 bonus to Armor Class against ranged attacks, but takes a –4 penalty to AC against melee attacks.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"shaken","name":"Abalado","summary":"Sofre –2 em ataques, testes de resistência, perícias e habilidades.","mechanical_effects":{"source_name":"Shaken","source_text":"A shaken character takes a –2 penalty on attack rolls, saving throws, skill checks, and ability checks.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"sickened","name":"Enjoado","summary":"Sofre –2 em ataques, dano, testes de resistência, perícias e habilidades.","mechanical_effects":{"source_name":"Sickened","source_text":"The character takes a –2 penalty on all attack rolls, weapon damage rolls, saving throws, skill checks, and ability checks.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"stable","name":"Estável","summary":"Está inconsciente, mas deixou de perder PV; ainda precisa recuperar-se para despertar.","mechanical_effects":{"source_name":"Stable","source_text":"A character who was dying but who has stopped losing hit points and still has negative hit points is stable. The character is no longer dying, but is still unconscious. If the character has become stable because of aid from another character (such as a Heal check or magical healing), then the character no longer loses hit points. He has a 10% chance each hour of becoming conscious and disabled (even though his hit points are still negative).","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"staggered","name":"Cambaleante","summary":"Só pode realizar uma ação padrão ou de movimento por rodada, sem combinar ações.","mechanical_effects":{"source_name":"Staggered","source_text":"A character whose nonlethal damage exactly equals his current hit points is staggered. A staggered character may take a single move action or standard action each round (but not both, nor can she take full-round actions).","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"stunned","name":"Atordoado","summary":"Larga o que segura, não age, sofre –2 na CA e perde o bônus de Destreza.","mechanical_effects":{"source_name":"Stunned","source_text":"A stunned creature drops everything held, can’t take actions, takes a –2 penalty to AC, and loses his Dexterity bonus to AC (if any).","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"turned","name":"Expulso","summary":"Mortos-vivos fogem por 10 rodadas, salvo se não puderem fugir.","mechanical_effects":{"source_name":"Turned","source_text":"Affected by a turn undead attempt. Turned undead flee for 10 rounds (1 minute) by the best and fastest means available to them. If they cannot flee, they cower.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"},{"condition_id":"unconscious","name":"Inconsciente","summary":"Está sem consciência, indefeso, derruba o que segurava e fica caído.","mechanical_effects":{"source_name":"Unconscious","source_text":"Knocked out and helpless. Unconsciousness can result from having current hit points between –1 and –9, or from nonlethal damage in excess of current hit points.","engine_status":"needs_implementation","source_section":"Special Abilities & Conditions / Conditions"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/conditionSummary.htm","verification_status":"needs_review"}]$conditions$::jsonb) AS x(
 condition_id text,name text,summary text,mechanical_effects jsonb,source_id text,source_url text,verification_status text
)
ON CONFLICT(condition_id) DO UPDATE SET
 name=EXCLUDED.name,summary=EXCLUDED.summary,
 mechanical_effects=EXCLUDED.mechanical_effects,
 source_id=EXCLUDED.source_id,source_url=EXCLUDED.source_url,
 verification_status=CASE WHEN public.srd_conditions.verification_status='verified_srd' THEN public.srd_conditions.verification_status ELSE EXCLUDED.verification_status END;

INSERT INTO public.srd_domains
(domain_id,name,granted_power_summary,mechanics,source_id,source_url,verification_status)
SELECT x.domain_id,x.name,x.granted_power_summary,x.mechanics,x.source_id,x.source_url,x.verification_status
FROM jsonb_to_recordset($domains$[{"domain_id":"air","name":"Ar","granted_power_summary":"Expulsar ou destruir criaturas da terra ou repreender, comandar ou fortalecer criaturas do ar conforme o alinhamento; usos por dia iguais a 3 + modificador de Carisma.","mechanics":{"source_name":"Air","source_granted_power":"Turn or destroy earth creatures as a good cleric turns undead. Rebuke, command, or bolster air creatures as an evil cleric rebukes undead. Use these abilities a total number of times per day equal to 3 + your Charisma modifier. This granted power is a supernatural ability.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"animal","name":"Animal","granted_power_summary":"Falar com animais uma vez por dia como habilidade similar a magia; Conhecimento (natureza) é perícia de classe.","mechanics":{"source_name":"Animal","source_granted_power":"You can use speak with animals once per day as a spell-like ability. Add Knowledge (nature) to your list of cleric class skills.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"chaos","name":"Caos","granted_power_summary":"Magias do caos recebem +1 nível de conjurador.","mechanics":{"source_name":"Chaos","source_granted_power":"You cast chaos spells at +1 caster level.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"death","name":"Morte","granted_power_summary":"Toque da morte uma vez por dia: ataque de toque e 1d6 por nível de clérigo; se alcançar os PV atuais, mata sem teste de resistência.","mechanics":{"source_name":"Death","source_granted_power":"You may use a death touch once per day. Your death touch is a supernatural ability that produces a death effect. You must succeed on a melee touch attack against a living creature (using the rules for touch spells). When you touch, roll 1d6 per cleric level you possess. If the total at least equals the creature’s current hit points, it dies (no save).","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"destruction","name":"Destruição","granted_power_summary":"Uma vez por dia, um ataque corpo a corpo recebe +4 para acertar e dano adicional igual ao nível de clérigo.","mechanics":{"source_name":"Destruction","source_granted_power":"You gain the smite power, the supernatural ability to make a single melee attack with a +4 bonus on attack rolls and a bonus on damage rolls equal to your cleric level (if you hit). You must declare the smite before making the attack. This ability is usable once per day.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"earth","name":"Terra","granted_power_summary":"Expulsar ou destruir criaturas do ar ou repreender, comandar ou fortalecer criaturas da terra conforme o alinhamento; usos por dia iguais a 3 + modificador de Carisma.","mechanics":{"source_name":"Earth","source_granted_power":"Turn or destroy air creatures as a good cleric turns undead. Rebuke, command, or bolster earth creatures as an evil cleric rebukes undead. Use these abilities a total number of times per day equal to 3 + your Charisma modifier. This granted power is a supernatural ability.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"evil","name":"Mal","granted_power_summary":"Magias malignas recebem +1 nível de conjurador.","mechanics":{"source_name":"Evil","source_granted_power":"You cast evil spells at +1 caster level.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"fire","name":"Fogo","granted_power_summary":"Expulsar ou destruir criaturas da água ou repreender, comandar ou fortalecer criaturas do fogo conforme o alinhamento; usos por dia iguais a 3 + modificador de Carisma.","mechanics":{"source_name":"Fire","source_granted_power":"Turn or destroy water creatures as a good cleric turns undead. Rebuke, command, or bolster fire creatures as an evil cleric rebukes undead. Use these abilities a total number of times per day equal to 3 + your Charisma modifier. This granted power is a supernatural ability.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"good","name":"Bem","granted_power_summary":"Magias bondosas recebem +1 nível de conjurador.","mechanics":{"source_name":"Good","source_granted_power":"You cast good spells at +1 caster level.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"healing","name":"Cura","granted_power_summary":"Magias de cura recebem +1 nível de conjurador.","mechanics":{"source_name":"Healing","source_granted_power":"You cast healing spells at +1 caster level.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"knowledge","name":"Conhecimento","granted_power_summary":"Todas as perícias de Conhecimento são perícias de classe; magias de adivinhação recebem +1 nível de conjurador.","mechanics":{"source_name":"Knowledge","source_granted_power":"Add all Knowledge skills to your list of cleric class skills. You cast divination spells at +1 caster level.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"law","name":"Ordem","granted_power_summary":"Magias da ordem recebem +1 nível de conjurador.","mechanics":{"source_name":"Law","source_granted_power":"You cast law spells at +1 caster level.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"luck","name":"Sorte","granted_power_summary":"Uma vez por dia, repita uma jogada e use o melhor resultado; habilidade extraordinária.","mechanics":{"source_name":"Luck","source_granted_power":"You gain the power of good fortune, which is usable once per day. This extraordinary ability allows you to reroll one roll that you have just made before the game master declares whether the roll results in success or failure. You must take the result of the reroll, even if it’s worse than the original roll.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"magic","name":"Magia","granted_power_summary":"Usa pergaminhos, varinhas e outros itens de ativação como um mago de nível igual ao de clérigo menos 3.","mechanics":{"source_name":"Magic","source_granted_power":"Use scrolls, wands, and other devices with spell completion or spell trigger activation as a wizard of one-half your cleric level (at least 1st level). For the purpose of using a scroll or other magic device, if you are also a wizard, actual wizard levels and these effective wizard levels stack.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"plant","name":"Plantas","granted_power_summary":"Expulsar ou comandar criaturas vegetais conforme o alinhamento; usos por dia iguais a 3 + modificador de Carisma.","mechanics":{"source_name":"Plant","source_granted_power":"Rebuke or command plant creatures as an evil cleric rebukes or commands undead. Use this ability a total number of times per day equal to 3 + your Charisma modifier. This granted power is a supernatural ability. Add Knowledge (nature) to your list of cleric class skills.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"protection","name":"Proteção","granted_power_summary":"Uma vez por dia, concede a criatura tocada bônus de resistência +1, aumentando em +1 a cada 5 níveis de clérigo.","mechanics":{"source_name":"Protection","source_granted_power":"You can generate a protective ward as a supernatural ability. Grant someone you touch a resistance bonus equal to your cleric level on his or her next saving throw. Activating this power is a standard action. The protective ward is an abjuration effect with a duration of 1 hour that is usable once per day.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"strength","name":"Força","granted_power_summary":"Uma vez por dia, recebe bônus de aprimoramento em Força por 1 rodada, igual ao nível de clérigo.","mechanics":{"source_name":"Strength","source_granted_power":"You can perform a feat of strength as a supernatural ability. You gain an enhancement bonus to Strength equal to your cleric level. Activating the power is a free action, the power lasts 1 round, and it is usable once per day.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"sun","name":"Sol","granted_power_summary":"Uma vez por dia, realiza uma expulsão maior de mortos-vivos em vez da expulsão normal.","mechanics":{"source_name":"Sun","source_granted_power":"Once per day, you can perform a greater turning against undead in place of a regular turning. The greater turning is like a normal turning except that the undead creatures that would be turned are destroyed instead.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"travel","name":"Viagem","granted_power_summary":"Por até 1 rodada por nível de clérigo por dia, age normalmente apesar de efeitos que limitariam seu movimento.","mechanics":{"source_name":"Travel","source_granted_power":"For a total time per day of 1 round per cleric level you possess, you can act normally regardless of magical effects that impede movement as if you were affected by the spell freedom of movement. This effect occurs automatically as soon as it applies, lasts until it runs out or is no longer needed, and can operate multiple times per day (up to the total daily limit of rounds). This granted power is a supernatural ability. Add Survival to your list of cleric class skills.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"trickery","name":"Trapaça","granted_power_summary":"Blefar, Disfarçar e Esconder-se são perícias de classe.","mechanics":{"source_name":"Trickery","source_granted_power":"Add Bluff, Disguise, and Hide to your list of cleric class skills.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"war","name":"Guerra","granted_power_summary":"Recebe proficiência com a arma favorita da divindade e Foco em Arma com ela.","mechanics":{"source_name":"War","source_granted_power":"Free Martial Weapon Proficiency with deity’s favored weapon (if necessary) and Weapon Focus with the deity’s favored weapon.","source_spell_count":9,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"},{"domain_id":"water","name":"Água","granted_power_summary":"Expulsar ou destruir criaturas do fogo ou repreender, comandar ou fortalecer criaturas da água conforme o alinhamento; usos por dia iguais a 3 + modificador de Carisma.","mechanics":{"source_name":"Water","source_granted_power":"Turn or destroy fire creatures as a good cleric turns undead. Rebuke, command, or bolster water creatures as an evil cleric rebukes undead. Use these abilities a total number of times per day equal to 3 + your Charisma modifier. This granted power is a supernatural ability.","source_spell_count":7,"engine_status":"needs_implementation"},"source_id":"dnd35-srd-ogl","source_url":"https://www.d20srd.org/srd/spellLists/clericDomains","verification_status":"needs_review"}]$domains$::jsonb) AS x(
 domain_id text,name text,granted_power_summary text,mechanics jsonb,source_id text,source_url text,verification_status text
)
ON CONFLICT(domain_id) DO UPDATE SET
 name=EXCLUDED.name,granted_power_summary=EXCLUDED.granted_power_summary,
 mechanics=EXCLUDED.mechanics,source_id=EXCLUDED.source_id,source_url=EXCLUDED.source_url,
