)
ON CONFLICT(class_id,class_level,feature_key) DO UPDATE SET
 name=EXCLUDED.name,summary=EXCLUDED.summary,mechanics=EXCLUDED.mechanics,source_id=EXCLUDED.source_id,
 verification_status=CASE WHEN public.srd_class_level_features.verification_status='verified_srd' THEN public.srd_class_level_features.verification_status ELSE EXCLUDED.verification_status END;

INSERT INTO public.srd_spell_effects
(spell_id,effect_index,effect_kind,target_kind,saving_throw,save_result,spell_resistance,damage_expression,duration_expression,parameters,source_id,verification_status)
SELECT s.id,1,'manual','manual_resolution',
 CASE WHEN lower(coalesce(s.dados_tecnicos->'source_field_values'->>'Saving Throw','')) LIKE 'fortitude%' THEN 'fortitude'
      WHEN lower(coalesce(s.dados_tecnicos->'source_field_values'->>'Saving Throw','')) LIKE 'reflex%' THEN 'reflex'
      WHEN lower(coalesce(s.dados_tecnicos->'source_field_values'->>'Saving Throw','')) LIKE 'will%' THEN 'will'
      ELSE NULL END,
 NULL,
 CASE WHEN lower(coalesce(s.dados_tecnicos->'source_field_values'->>'Spell Resistance','')) LIKE 'yes%' THEN true
      WHEN lower(coalesce(s.dados_tecnicos->'source_field_values'->>'Spell Resistance','')) LIKE 'no%' THEN false
      ELSE NULL END,
 NULL,
 s.dados_tecnicos->'source_field_values'->>'Duration',
 jsonb_build_object('spell_name',s.nome,'source_fields',coalesce(s.dados_tecnicos->'source_field_values','{}'::jsonb),'description_pt',s.descricao,'resolution','manual_only','audit_note','Nenhum dano, salvamento, condição ou cura é aplicado automaticamente por este registro.'),
 coalesce(s.source_id,'dnd35-srd-ogl'),'manual_only'
FROM public.srd_spells s
ON CONFLICT(spell_id,effect_index) DO NOTHING;

INSERT INTO public.srd_catalog_coverage
(catalog_key,ruleset_id,expected_entries,actual_entries,verified_entries,audit_status,audit_notes,updated_at)
VALUES ('domain_spells','dnd35-srd',196,(SELECT count(*) FROM public.srd_domain_spells),0,'in_progress',
 '196 entradas do SRD importadas com fonte; mapeamento e conjuração por domínio ainda precisam de revisão.',now())
ON CONFLICT(catalog_key) DO NOTHING;

UPDATE public.srd_catalog_coverage c
SET expected_entries=CASE c.catalog_key
  WHEN 'conditions' THEN 38 WHEN 'domains' THEN 22 WHEN 'domain_spells' THEN 196
  WHEN 'class_features' THEN 131 WHEN 'classes' THEN 11 WHEN 'spells' THEN 607
  WHEN 'spell_effects' THEN 607 ELSE c.expected_entries END,
 actual_entries=CASE c.catalog_key
  WHEN 'conditions' THEN (SELECT count(*) FROM public.srd_conditions)
  WHEN 'domains' THEN (SELECT count(*) FROM public.srd_domains)
  WHEN 'domain_spells' THEN (SELECT count(*) FROM public.srd_domain_spells)
  WHEN 'class_features' THEN (SELECT count(*) FROM public.srd_class_level_features)
  WHEN 'classes' THEN (SELECT count(*) FROM public.srd_classes)
  WHEN 'spells' THEN (SELECT count(*) FROM public.srd_spells)
  WHEN 'spell_effects' THEN (SELECT count(*) FROM public.srd_spell_effects)
  ELSE c.actual_entries END,
 verified_entries=CASE c.catalog_key
  WHEN 'conditions' THEN (SELECT count(*) FROM public.srd_conditions WHERE verification_status='verified_srd')
  WHEN 'domains' THEN (SELECT count(*) FROM public.srd_domains WHERE verification_status='verified_srd')
  WHEN 'domain_spells' THEN (SELECT count(*) FROM public.srd_domain_spells WHERE verification_status='verified_srd')
  WHEN 'class_features' THEN (SELECT count(*) FROM public.srd_class_level_features WHERE verification_status='verified_srd')
  WHEN 'spells' THEN (SELECT count(*) FROM public.srd_spells WHERE source_status='verified_srd')
  WHEN 'spell_effects' THEN (SELECT count(*) FROM public.srd_spell_effects WHERE verification_status='verified_srd')
  ELSE c.verified_entries END,
 audit_status=CASE c.catalog_key WHEN 'conditions' THEN 'in_progress' WHEN 'domains' THEN 'in_progress' WHEN 'domain_spells' THEN 'in_progress' WHEN 'class_features' THEN 'in_progress' WHEN 'classes' THEN 'in_progress' WHEN 'spells' THEN 'in_progress' WHEN 'spell_effects' THEN 'in_progress' ELSE c.audit_status END,
 audit_notes=CASE c.catalog_key
  WHEN 'conditions' THEN '38 estados SRD com resumo PT-BR e texto-fonte atribuído; efeitos não estão conectados integralmente ao motor. Revisão mecânica pendente.'
  WHEN 'domains' THEN '22 domínios do SRD com poderes traduzidos e fonte original preservada; verificação de todas as interações pendente.'
  WHEN 'domain_spells' THEN '196 entradas das listas oficiais dos domínios; 6 magias faltantes foram adicionadas em estado não verificado. Conferir círculo, acesso e conjuração por domínio.'
  WHEN 'class_features' THEN '131 entradas das tabelas de classe traduzidas e atribuídas; requisitos e execução de cada característica ainda precisam de implementação e revisão.'
  WHEN 'classes' THEN '11 classes básicas; progressões por nível já existem. Auditoria das características e regras derivadas segue em andamento.'
  WHEN 'spells' THEN '607 registros catalogados após inclusão de seis magias ausentes nas listas de domínio. Dados e descrições ainda não foram auditados linha a linha.'
  WHEN 'spell_effects' THEN 'Um registro de controle manual por magia, com campos-fonte preservados. Os efeitos ainda NÃO são automatizados; não interpretar a contagem como motor concluído.'
  ELSE c.audit_notes END,
 updated_at=now()
WHERE c.ruleset_id='dnd35-srd';

COMMIT